-- Seed the LotusFunds brand shown in the supplied Daily Market Dashboard.
-- The event guard keeps later user edits from being overwritten on restart.
CREATE TABLE IF NOT EXISTS app_seed_events (
  name text PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now()
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM app_seed_events
    WHERE name = '20261104_lotusfunds_company_brand'
  ) THEN
    INSERT INTO employee_company_brands (
      name, color, recipient_email, logo_mime, logo_data
    )
    VALUES (
      'LotusFunds',
      '#c00078',
      'pradyut@lotusfunds.com',
      'image/png',
      decode('', 'base64')
    )
    ON CONFLICT (lower(name)) DO UPDATE
    SET color = EXCLUDED.color,
        recipient_email = COALESCE(employee_company_brands.recipient_email, EXCLUDED.recipient_email),
        logo_mime = EXCLUDED.logo_mime,
        logo_data = EXCLUDED.logo_data,
        updated_at = now();

    INSERT INTO app_seed_events (name)
    VALUES ('20261104_lotusfunds_company_brand');
  END IF;
END $$;
